package dev.shadowsoffire.apotheosis.affix.effect;

import java.util.Set;
import java.util.stream.Collectors;
import java.util.stream.Stream;

import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;

import dev.shadowsoffire.apotheosis.Apoth;
import dev.shadowsoffire.apotheosis.Apoth.LootCategories;
import dev.shadowsoffire.apotheosis.Apotheosis;
import dev.shadowsoffire.apotheosis.affix.Affix;
import dev.shadowsoffire.apotheosis.affix.AffixDefinition;
import dev.shadowsoffire.apotheosis.affix.AffixHelper;
import dev.shadowsoffire.apotheosis.affix.AffixInstance;
import dev.shadowsoffire.apotheosis.attachments.AttributeToggles;
import dev.shadowsoffire.apotheosis.loot.LootCategory;
import dev.shadowsoffire.apotheosis.loot.LootRarity;
import dev.shadowsoffire.apotheosis.net.AttributeTogglesPayload;
import dev.shadowsoffire.placebo.codec.PlaceboCodecs;
import net.minecraft.ChatFormatting;
import net.minecraft.core.Holder;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.network.chat.CommonComponents;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.MutableComponent;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.EquipmentSlot;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.ai.attributes.Attribute;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.neoforged.neoforge.common.util.AttributeTooltipContext;
import net.neoforged.neoforge.network.PacketDistributor;

/**
 * Boots ability affix that lets the wearer toggle all bonuses to one or more attributes on or off with a keybind.
 * <p>
 * All attributes of a single affix are toggled together: if any of them is currently suppressed, the key re-enables all of them,
 * otherwise it suppresses all of them.
 * <p>
 * While suppressed, {@link LivingEntity#getAttributeValue(Holder)} clamps the attribute for the wearer down to its base value,
 * carving out the vanilla sprint boost. Net penalties still pass through (see {@link AttributeToggles#getCappedValue}).
 * <p>
 * The player's choice is stored in {@link Apoth.Attachments#ATTRIBUTE_TOGGLES} and is cleared as soon as the boots granting it
 * are removed (see {@link #prune(ServerPlayer)}).
 */
public class AttributeToggleAffix extends Affix {

    public static final String TOGGLE_KEY = Apotheosis.langKey("key", "toggle_attribute_bonuses");

    public static final Codec<AttributeToggleAffix> CODEC = RecordCodecBuilder.create(inst -> inst
        .group(
            affixDef(),
            PlaceboCodecs.setOf(BuiltInRegistries.ATTRIBUTE.holderByNameCodec()).fieldOf("attributes").forGetter(a -> a.attributes),
            PlaceboCodecs.setOf(LootRarity.CODEC).fieldOf("rarities").forGetter(a -> a.rarities))
        .apply(inst, AttributeToggleAffix::new));

    protected final Set<Holder<Attribute>> attributes;
    protected final Set<LootRarity> rarities;

    public AttributeToggleAffix(AffixDefinition def, Set<Holder<Attribute>> attributes, Set<LootRarity> rarities) {
        super(def);
        this.attributes = attributes;
        this.rarities = rarities;
    }

    public Set<Holder<Attribute>> getAttributes() {
        return this.attributes;
    }

    @Override
    public boolean canApplyTo(ItemStack stack, LootCategory cat, LootRarity rarity) {
        return cat == LootCategories.BOOTS && this.rarities.contains(rarity);
    }

    @Override
    public MutableComponent getDescription(AffixInstance inst, AttributeTooltipContext ctx) {
        MutableComponent desc = Component.translatable("affix." + this.id() + ".desc", Component.keybind(TOGGLE_KEY));
        Player player = ctx.player();
        if (player != null) {
            AttributeToggles toggles = getToggles(player);
            boolean suppressed = this.attributes.stream().allMatch(toggles::isSuppressed);
            MutableComponent state = Apotheosis.lang("misc", "attribute_toggle." + (suppressed ? "off" : "on"))
                .withStyle(suppressed ? ChatFormatting.RED : ChatFormatting.GREEN);
            desc.append(CommonComponents.SPACE).append(Apotheosis.lang("misc", "attribute_toggle.state", state));
        }
        return desc;
    }

    @Override
    public Codec<? extends Affix> getCodec() {
        return CODEC;
    }

    @Override
    public boolean isLevelIndependent(AffixInstance inst) {
        return true;
    }

    // Static helpers

    public static AttributeToggles getToggles(Player player) {
        return player.getData(Apoth.Attachments.ATTRIBUTE_TOGGLES);
    }

    public static void setToggles(Player player, AttributeToggles toggles) {
        player.setData(Apoth.Attachments.ATTRIBUTE_TOGGLES, toggles);
    }

    /**
     * Streams every toggle affix present on the player's currently-worn boots.
     */
    public static Stream<AttributeToggleAffix> streamWornAffixes(Player player) {
        return AffixHelper.streamAffixes(player.getItemBySlot(EquipmentSlot.FEET))
            .map(AffixInstance::getAffix)
            .filter(AttributeToggleAffix.class::isInstance)
            .map(AttributeToggleAffix.class::cast);
    }

    /**
     * Collects every attribute that the player's worn boots allow toggling.
     */
    public static Set<Holder<Attribute>> getWornAttributes(Player player) {
        return streamWornAffixes(player).flatMap(a -> a.attributes.stream()).collect(Collectors.toSet());
    }

    /**
     * Drops any suppressed attributes that are no longer provided by the player's worn boots, syncing to the client if anything changed.
     * <p>
     * Called when the boots slot changes and when the player joins a level.
     */
    public static void prune(ServerPlayer player) {
        AttributeToggles toggles = getToggles(player);
        if (toggles.isEmpty()) {
            return;
        }
        AttributeToggles pruned = toggles.retain(getWornAttributes(player));
        if (pruned != toggles) {
            setToggles(player, pruned);
            sync(player);
        }
    }

    /**
     * Server-side handler for the toggle keybind. If any attribute provided by the worn boots is suppressed, all of them are
     * re-enabled; otherwise all of them are suppressed. The result is synced to the client.
     */
    public static void handleToggle(ServerPlayer player) {
        Set<Holder<Attribute>> attrs = getWornAttributes(player);
        if (attrs.isEmpty()) {
            player.sendSystemMessage(Apotheosis.sysMessageHeader().append(Apotheosis.lang("misc", "attribute_toggle.none").withStyle(ChatFormatting.YELLOW)));
            return;
        }

        AttributeToggles toggles = getToggles(player);
        boolean suppress = attrs.stream().noneMatch(toggles::isSuppressed);
        setToggles(player, toggles.withSuppressed(attrs, suppress));
        sync(player);

        MutableComponent state = Apotheosis.lang("misc", "attribute_toggle." + (suppress ? "off" : "on"))
            .withStyle(suppress ? ChatFormatting.RED : ChatFormatting.GREEN);
        for (Holder<Attribute> attr : attrs) {
            Component attrName = Component.translatable(attr.value().getDescriptionId());
            player.sendSystemMessage(Apotheosis.sysMessageHeader().append(Apotheosis.lang("misc", "attribute_toggle.updated", attrName, state).withStyle(ChatFormatting.YELLOW)));
        }
    }

    public static void sync(ServerPlayer player) {
        PacketDistributor.sendToPlayer(player, new AttributeTogglesPayload(getToggles(player)));
    }

}

package dev.shadowsoffire.apotheosis.attachments;

import java.util.HashSet;
import java.util.Set;

import com.mojang.serialization.Codec;

import dev.shadowsoffire.apotheosis.affix.effect.AttributeToggleAffix;
import dev.shadowsoffire.apotheosis.util.AttributeInstanceExt;
import dev.shadowsoffire.placebo.codec.PlaceboCodecs;
import it.unimi.dsi.fastutil.objects.Reference2ObjectArrayMap;
import net.minecraft.core.Holder;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.core.registries.Registries;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.codec.ByteBufCodecs;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.resources.Identifier;
import net.minecraft.world.entity.ai.attributes.Attribute;
import net.minecraft.world.entity.ai.attributes.AttributeInstance;
import net.minecraft.world.entity.ai.attributes.AttributeModifier;
import net.minecraft.world.entity.ai.attributes.AttributeModifier.Operation;

/**
 * Holds the set of attributes whose bonuses a player has elected to suppress via an {@link AttributeToggleAffix}.
 * <p>
 * Suppression is a clamp. An attribute's value is limited to its base value (plus the vanilla sprint boost, which is
 * carved out). The final value is {@code min(actual, cap)}. Technically speaking we have four cases:
 * <ul>
 * <li>Bonuses alone: clamped to the base value.</li>
 * <li>Penalties alone (e.g. Slowness): unchanged, the player stays slowed.</li>
 * <li>Bonuses outweighing penalties (e.g. Speed V + Slowness I): clamped to the base value, the player is <em>not</em> slowed.</li>
 * <li>Penalties outweighing bonuses: unchanged, the net-slowed value passes through.</li>
 * </ul>
 */
public final class AttributeToggles {

    public static final AttributeToggles EMPTY = new AttributeToggles(Set.of());

    public static final Codec<AttributeToggles> CODEC = PlaceboCodecs.setOf(BuiltInRegistries.ATTRIBUTE.holderByNameCodec())
        .xmap(AttributeToggles::new, AttributeToggles::suppressed);

    public static final StreamCodec<RegistryFriendlyByteBuf, AttributeToggles> STREAM_CODEC = ByteBufCodecs.holderRegistry(Registries.ATTRIBUTE)
        .<Set<Holder<Attribute>>>apply(ByteBufCodecs.collection(HashSet::new))
        .map(AttributeToggles::new, AttributeToggles::suppressed);

    /**
     * Id of {@code LivingEntity#SPEED_MODIFIER_SPRINTING}, the transient +30% multiplied-total modifier applied while sprinting.
     */
    public static final Identifier SPRINTING_MODIFIER_ID = Identifier.withDefaultNamespace("sprinting");

    private final Set<Holder<Attribute>> suppressed;

    /**
     * Transient cache of computed caps. Small array map since a player rarely suppresses more than one attribute.
     */
    private final Reference2ObjectArrayMap<Holder<Attribute>, CapEntry> capCache = new Reference2ObjectArrayMap<>(2);

    public AttributeToggles(Set<Holder<Attribute>> suppressed) {
        this.suppressed = Set.copyOf(suppressed);
    }

    public Set<Holder<Attribute>> suppressed() {
        return this.suppressed;
    }

    public boolean isEmpty() {
        return this.suppressed.isEmpty();
    }

    public boolean isSuppressed(Holder<Attribute> attribute) {
        return !this.suppressed.isEmpty() && this.suppressed.contains(attribute);
    }

    /**
     * Returns a copy of this object with every attribute in {@code attributes} set to the given suppression state.
     */
    public AttributeToggles withSuppressed(Set<Holder<Attribute>> attributes, boolean suppressed) {
        Set<Holder<Attribute>> copy = new HashSet<>(this.suppressed);
        if (suppressed) {
            copy.addAll(attributes);
        }
        else {
            copy.removeAll(attributes);
        }
        return copy.equals(this.suppressed) ? this : copy.isEmpty() ? EMPTY : new AttributeToggles(copy);
    }

    /**
     * Returns this object if every suppressed attribute is in {@code allowed}, otherwise a copy retaining only the allowed ones.
     */
    public AttributeToggles retain(Set<Holder<Attribute>> allowed) {
        if (allowed.containsAll(this.suppressed)) {
            return this;
        }
        Set<Holder<Attribute>> copy = new HashSet<>(this.suppressed);
        copy.retainAll(allowed);
        return copy.isEmpty() ? EMPTY : new AttributeToggles(copy);
    }

    /**
     * Computes the suppressed value of an attribute instance.
     * <p>
     * The result is {@code min(actualValue, cap)}, where {@code cap} is the attribute value calculated with every modifier
     * removed except {@link #SPRINTING_MODIFIER_ID}. The cap is cached against the instance's modification counter.
     */
    public double getCappedValue(AttributeInstance inst) {
        AttributeInstanceExt ext = AttributeInstanceExt.of(inst);
        int modCount = ext.apoth$getModificationCount();

        CapEntry entry = this.capCache.get(inst.getAttribute());
        if (entry == null) {
            entry = new CapEntry();
            this.capCache.put(inst.getAttribute(), entry);
        }
        if (entry.modCount != modCount || !entry.valid) {
            entry.cap = computeCap(inst);
            entry.modCount = modCount;
            entry.valid = true;
        }

        return Math.min(inst.getValue(), entry.cap);
    }

    /**
     * Mirrors {@code AttributeInstance#calculateValue()}, skipping any modifier rejected by {@link #isRetained(AttributeModifier)}.
     */
    private static double computeCap(AttributeInstance inst) {
        double base = inst.getBaseValue();

        for (AttributeModifier mod : inst.getModifiers(Operation.ADD_VALUE).values()) {
            if (isRetained(mod)) {
                base += mod.amount();
            }
        }

        double result = base;

        for (AttributeModifier mod : inst.getModifiers(Operation.ADD_MULTIPLIED_BASE).values()) {
            if (isRetained(mod)) {
                result += base * mod.amount();
            }
        }

        for (AttributeModifier mod : inst.getModifiers(Operation.ADD_MULTIPLIED_TOTAL).values()) {
            if (isRetained(mod)) {
                result *= 1.0 + mod.amount();
            }
        }

        return inst.getAttribute().value().sanitizeValue(result);
    }

    /**
     * We explicitly ignore sprinting since we still want the player to be able to sprint when speed boosts are disabled.
     */
    private static boolean isRetained(AttributeModifier mod) {
        return SPRINTING_MODIFIER_ID.equals(mod.id());
    }

    @Override
    public boolean equals(Object obj) {
        return obj instanceof AttributeToggles other && this.suppressed.equals(other.suppressed);
    }

    @Override
    public int hashCode() {
        return this.suppressed.hashCode();
    }

    @Override
    public String toString() {
        return "AttributeToggles" + this.suppressed;
    }

    private static final class CapEntry {
        int modCount;
        double cap;
        boolean valid;
    }

}

package dev.shadowsoffire.apotheosis.net;

import java.util.List;
import java.util.Optional;

import dev.shadowsoffire.apotheosis.Apotheosis;
import dev.shadowsoffire.apotheosis.affix.effect.AttributeToggleAffix;
import dev.shadowsoffire.apotheosis.attachments.AttributeToggles;
import dev.shadowsoffire.placebo.network.PayloadProvider;
import net.minecraft.network.ConnectionProtocol;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.network.protocol.PacketFlow;
import net.minecraft.network.protocol.common.custom.CustomPacketPayload;
import net.minecraft.server.level.ServerPlayer;
import net.neoforged.neoforge.network.handling.IPayloadContext;

/**
 * Payload for {@link AttributeToggles} state.
 * <p>
 * When sent to the server, it toggles every attribute provided by the player's worn {@link AttributeToggleAffix}es, ignoring {@link #toggles}.
 * <p>
 * When sent to the client, it replaces the player's toggle state with {@link #toggles}.
 */
public record AttributeTogglesPayload(AttributeToggles toggles) implements CustomPacketPayload {

    public static final Type<AttributeTogglesPayload> TYPE = new Type<>(Apotheosis.loc("attribute_toggles"));

    public static final StreamCodec<RegistryFriendlyByteBuf, AttributeTogglesPayload> CODEC = AttributeToggles.STREAM_CODEC.map(AttributeTogglesPayload::new, AttributeTogglesPayload::toggles);

    public AttributeTogglesPayload() {
        this(AttributeToggles.EMPTY); // When sent to the server, the payload contents are ignored.
    }

    @Override
    public Type<? extends CustomPacketPayload> type() {
        return TYPE;
    }

    public static class Provider implements PayloadProvider<AttributeTogglesPayload> {

        @Override
        public Type<AttributeTogglesPayload> getType() {
            return TYPE;
        }

        @Override
        public StreamCodec<? super RegistryFriendlyByteBuf, AttributeTogglesPayload> getCodec() {
            return CODEC;
        }

        @Override
        public void handleClient(AttributeTogglesPayload msg, IPayloadContext ctx) {
            AttributeToggleAffix.setToggles(ctx.player(), msg.toggles);
        }

        @Override
        public void handleServer(AttributeTogglesPayload msg, IPayloadContext ctx) {
            if (ctx.player() instanceof ServerPlayer sp) {
                AttributeToggleAffix.handleToggle(sp);
            }
        }

        @Override
        public List<ConnectionProtocol> getSupportedProtocols() {
            return List.of(ConnectionProtocol.PLAY);
        }

        @Override
        public Optional<PacketFlow> getFlow() {
            return Optional.empty();
        }

        @Override
        public String getVersion() {
            return "1";
        }

    }

}

package dev.shadowsoffire.apotheosis.mixin;

import org.jetbrains.annotations.Nullable;
import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.Unique;
import org.spongepowered.asm.mixin.injection.At;
import org.spongepowered.asm.mixin.injection.Inject;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfoReturnable;

import dev.shadowsoffire.apotheosis.Apoth;
import dev.shadowsoffire.apotheosis.affix.effect.AttributeToggleAffix;
import dev.shadowsoffire.apotheosis.attachments.AttributeToggles;
import net.minecraft.core.Holder;
import net.minecraft.world.entity.ai.attributes.Attribute;
import net.minecraft.world.entity.ai.attributes.AttributeInstance;

import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.player.Player;

@Mixin(value = LivingEntity.class, remap = false)
public class LivingEntityMixin {

    @Unique
    @Nullable
    private Float originalHealthPercent;

    /**
     * Called from the head of {@link LivingEntity#detectEquipmentUpdates()} to record the original health percentage for non-player entities.
     */
    @Inject(method = "detectEquipmentUpdates", at = @At("HEAD"))
    private void apoth_cacheLastHealthPct(CallbackInfo ci) {
        if (!this.isPlayer()) {
            LivingEntity self = (LivingEntity) (Object) this;
            if (self.getHealth() > 0 && self.getMaxHealth() > 0) {
                this.originalHealthPercent = self.getHealth() / self.getMaxHealth();
            }
            else {
                this.originalHealthPercent = null;
            }
        }
    }

    /**
     * Then, from the tail of the same method, we update the health to keep the same percentage.
     * <p>
     * Generally speaking, we want entities equipped with armor that increases their health to do so immediately, since mobs don't heal.
     */
    @Inject(method = "detectEquipmentUpdates", at = @At("TAIL"))
    private void apoth_updateHealthPct(CallbackInfo ci) {
        if (this.originalHealthPercent != null) {
            LivingEntity self = (LivingEntity) (Object) this;
            self.setHealth(self.getMaxHealth() * this.originalHealthPercent);
            this.originalHealthPercent = null;
        }
    }

    /**
     * Caps the attribute value for players who have suppressed bonuses to it via an {@link AttributeToggleAffix}.
     * <p>
     * See {@link AttributeToggles#getCappedValue(AttributeInstance)} for the clamping rules.
     */
    @Inject(method = "getAttributeValue", at = @At("HEAD"), cancellable = true)
    private void apoth_suppressToggledAttributes(Holder<Attribute> attribute, CallbackInfoReturnable<Double> cir) {
        if ((Object) this instanceof Player player) {
            AttributeToggles toggles = player.getData(Apoth.Attachments.ATTRIBUTE_TOGGLES);
            if (toggles.isSuppressed(attribute)) {
                AttributeInstance inst = player.getAttributes().getInstance(attribute);
                if (inst != null) {
                    cir.setReturnValue(toggles.getCappedValue(inst));
                }
            }
        }
    }

    private boolean isPlayer() {
        return (Object) this instanceof Player;
    }
}

package dev.shadowsoffire.apotheosis.mixin;

import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.Unique;
import org.spongepowered.asm.mixin.injection.At;
import org.spongepowered.asm.mixin.injection.Inject;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;

import dev.shadowsoffire.apotheosis.util.AttributeInstanceExt;
import net.minecraft.world.entity.ai.attributes.AttributeInstance;

/**
 * Implements {@link AttributeInstanceExt} for {@link AttributeInstance}.
 */
@Mixin(value = AttributeInstance.class, remap = false)
public abstract class AttributeInstanceMixin implements AttributeInstanceExt {

    @Unique
    private int apoth$modCount = 0;

    /**
     * Every mutation of an {@link AttributeInstance} (base value, add/remove modifier, replaceFrom) routes through {@code setDirty()}.
     */
    @Inject(method = "setDirty", at = @At("HEAD"))
    private void apoth_bumpModCount(CallbackInfo ci) {
        this.apoth$modCount++;
    }

    @Override
    public int apoth$getModificationCount() {
        return this.apoth$modCount;
    }
}

package dev.shadowsoffire.apotheosis.util;

import net.minecraft.world.entity.ai.attributes.AttributeInstance;

public interface AttributeInstanceExt {

    /**
     * Returns a counter that increments every time the base value or modifier set of this instance changes.
     */
    int apoth$getModificationCount();

    static AttributeInstanceExt of(AttributeInstance inst) {
        return (AttributeInstanceExt) inst;
    }

}

